import { type FormEvent, type ReactNode, useEffect, useMemo, useState } from 'react';
import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { Link, Redirect, Route, Switch, useLocation, useRoute } from 'wouter';
import {
  AlertTriangle, ArrowDown, ArrowLeft, ArrowRight, Bell, CalendarDays, Check, ChevronDown,
  ChevronLeft, ChevronRight, CircleAlert, ClipboardList, Clock3, ExternalLink, FlaskConical,
  History, LayoutDashboard, LogOut, Menu, Package, Pencil, Plus, Search, Settings,
  ShieldCheck, SlidersHorizontal, Trash2, TrendingDown, TrendingUp, UserRound, X, Zap,
} from 'lucide-react';
import {
  getGetInventorySummaryQueryKey, getGetMedicineInventoryQueryKey, getGetMedicineQueryKey,
  getGetPharmacyQueryKey, getGetMeQueryKey, getListBatchesQueryKey, getListDispensingQueryKey,
  getListExpiredAlertsQueryKey, getListExpiringAlertsQueryKey, getListMedicinesQueryKey,
  getSearchInventoryQueryKey,
  useCreateBatch, useCreateMedicine, useDeleteBatch, useDeleteMedicine, useDispense,
  useGetInventorySummary, useGetMedicine, useGetMedicineInventory, useGetMe, useGetPharmacy,
  useListBatches, useListDispensing, useListExpiredAlerts, useListExpiringAlerts,
  useListMedicines, useLogin, useLogout, useRegister, useSearchInventory, useUpdateBatch,
  useUpdateMedicine, useUpdatePharmacy,
} from '@workspace/api-client-react';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import NotFound from '@/pages/not-found';

const queryClient = new QueryClient();
const cx = (...classes: Array<string | false | undefined>) => classes.filter(Boolean).join(' ');
const fmtDate = (value?: string | null) => value ? new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }).format(new Date(value)) : '—';
const fmtDateTime = (value?: string | null) => value ? new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }).format(new Date(value)) : '—';
const money = (value: number) => `£${Number(value || 0).toFixed(2)}`;

function Brand({ compact = false }: { compact?: boolean }) {
  return <Link href="/" className={cx('flex items-center gap-3', compact && 'justify-center')} data-testid="link-brand">
    <span className="grid h-9 w-9 place-items-center rounded-xl bg-primary text-primary-foreground shadow-sm">
      <FlaskConical size={19} strokeWidth={2.5} />
    </span>
    {!compact && <span className="font-semibold tracking-tight text-[17px]">Pharma<span className="text-accent">Flow</span></span>}
  </Link>;
}

function Button({ children, variant = 'primary', className, ...props }: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'ghost' | 'outline' | 'danger' | 'soft' }) {
  return <button {...props} className={cx(
    'inline-flex min-h-10 items-center justify-center gap-2 rounded-lg px-4 text-sm font-semibold transition-all duration-200 disabled:cursor-not-allowed disabled:opacity-45',
    variant === 'primary' && 'bg-primary text-primary-foreground shadow-sm hover:-translate-y-0.5 hover:shadow-md',
    variant === 'outline' && 'border border-border bg-card text-foreground hover:border-primary/50 hover:bg-secondary/50',
    variant === 'ghost' && 'text-muted-foreground hover:bg-secondary hover:text-foreground',
    variant === 'danger' && 'bg-destructive text-destructive-foreground hover:brightness-95',
    variant === 'soft' && 'bg-secondary text-secondary-foreground hover:bg-secondary/70',
    className
  )} />;
}

function Field({ label, value, onChange, type = 'text', placeholder, required = false, min, step, autoComplete }: { label: string; value: string | number; onChange: (value: string) => void; type?: string; placeholder?: string; required?: boolean; min?: number; step?: number; autoComplete?: string }) {
  return <label className="grid gap-1.5 text-sm font-medium text-foreground">
    <span>{label}{required && <span className="ml-1 text-accent">*</span>}</span>
    <input data-testid={`input-${label.toLowerCase().replaceAll(' ', '-')}`} required={required} type={type} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} min={min} step={step} autoComplete={autoComplete}
      className="h-11 rounded-lg border border-input bg-background px-3.5 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15" />
  </label>;
}

function TextareaField({ label, value, onChange, placeholder }: { label: string; value: string; onChange: (value: string) => void; placeholder?: string }) {
  return <label className="grid gap-1.5 text-sm font-medium text-foreground"><span>{label}</span>
    <textarea data-testid={`textarea-${label.toLowerCase().replaceAll(' ', '-')}`} value={value} onChange={(e) => onChange(e.target.value)} placeholder={placeholder} rows={3} className="rounded-lg border border-input bg-background px-3.5 py-3 text-sm outline-none transition focus:border-primary focus:ring-2 focus:ring-primary/15" />
  </label>;
}

function StatusBadge({ status }: { status: string }) {
  const labels: Record<string, string> = { in_stock: 'In stock', low_stock: 'Low stock', out_of_stock: 'Out of stock', expired_only: 'Expired only', active: 'Active', expiring_soon: 'Expiring soon', expired: 'Expired', depleted: 'Depleted' };
  return <span data-testid={`status-${status}`} className={cx('inline-flex w-fit items-center gap-1.5 rounded-full px-2.5 py-1 text-[11px] font-bold uppercase tracking-[.08em]',
    ['expired', 'expired_only'].includes(status) && 'bg-red-100 text-red-700', status === 'expiring_soon' && 'bg-amber-100 text-amber-800',
    ['low_stock'].includes(status) && 'bg-orange-100 text-orange-800', ['out_of_stock', 'depleted'].includes(status) && 'bg-muted text-muted-foreground',
    ['in_stock', 'active'].includes(status) && 'bg-teal-100 text-teal-800')}>
    <span className="h-1.5 w-1.5 rounded-full bg-current" />{labels[status] ?? status}
  </span>;
}

function EmptyState({ icon: Icon = Package, title, body, action }: { icon?: typeof Package; title: string; body: string; action?: ReactNode }) {
  return <div className="grid min-h-52 place-items-center rounded-xl border border-dashed border-border bg-card px-6 py-12 text-center">
    <div><div className="mx-auto mb-3 grid h-11 w-11 place-items-center rounded-full bg-secondary text-primary"><Icon size={20} /></div>
      <h3 className="font-semibold">{title}</h3><p className="mx-auto mt-1 max-w-sm text-sm text-muted-foreground">{body}</p>{action && <div className="mt-4">{action}</div>}</div>
  </div>;
}

function ErrorState({ onRetry }: { onRetry: () => void }) {
  return <div className="rounded-xl border border-red-200 bg-red-50 p-6 text-center"><CircleAlert className="mx-auto text-destructive" size={24} /><h3 className="mt-2 font-semibold text-red-900">We couldn’t load this view</h3><p className="mt-1 text-sm text-red-800/75">Check your connection and try again.</p><Button onClick={onRetry} variant="outline" className="mt-4">Try again</Button></div>;
}

function Skeleton({ rows = 4 }: { rows?: number }) {
  return <div className="space-y-3" data-testid="loading-skeleton">{Array.from({ length: rows }).map((_, i) => <div key={i} className="skeleton h-14 rounded-lg" />)}</div>;
}

function Pagination({ page, totalPages, onPage }: { page: number; totalPages: number; onPage: (page: number) => void }) {
  if (!totalPages || totalPages < 2) return null;
  return <div className="flex items-center justify-between border-t border-border pt-4 text-sm">
    <span className="text-muted-foreground">Page <strong className="text-foreground">{page}</strong> of {totalPages}</span>
    <div className="flex gap-1"><Button data-testid="button-page-previous" aria-label="Previous page" variant="outline" className="h-9 min-h-0 w-9 p-0" disabled={page <= 1} onClick={() => onPage(page - 1)}><ChevronLeft size={16} /></Button>
      <Button data-testid="button-page-next" aria-label="Next page" variant="outline" className="h-9 min-h-0 w-9 p-0" disabled={page >= totalPages} onClick={() => onPage(page + 1)}><ChevronRight size={16} /></Button></div>
  </div>;
}

const navItems = [
  { href: '/dashboard', label: 'Overview', icon: LayoutDashboard },
  { href: '/medicines', label: 'Medicines', icon: Package },
  { href: '/dispense', label: 'Dispense', icon: Zap },
  { href: '/alerts', label: 'Expiry watch', icon: Bell },
  { href: '/history', label: 'History', icon: History },
];

function Shell({ children }: { children: ReactNode }) {
  const [location, setLocation] = useLocation();
  const [open, setOpen] = useState(false);
  const me = useGetMe({ query: { queryKey: getGetMeQueryKey(), retry: false } });
  const logout = useLogout();
  useEffect(() => { if (me.isError) setLocation('/login'); }, [me.isError, setLocation]);
  if (me.isLoading) return <div className="min-h-[100dvh] bg-background p-6"><div className="mx-auto max-w-7xl"><div className="skeleton h-8 w-40 rounded" /><div className="mt-10"><Skeleton rows={6} /></div></div></div>;
  if (me.isError || !me.data) return null;
  const initials = me.data.name.split(' ').map((word) => word[0]).slice(0, 2).join('').toUpperCase();
  return <div className="grain min-h-[100dvh] bg-background">
    <aside className={cx('fixed inset-y-0 left-0 z-30 w-64 border-r border-border bg-card px-4 py-5 transition-transform duration-200 lg:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}>
      <div className="flex items-center justify-between px-2"><Brand /><button className="text-muted-foreground lg:hidden" onClick={() => setOpen(false)} aria-label="Close menu" data-testid="button-close-menu"><X size={20} /></button></div>
      <div className="mt-10 px-2 text-[10px] font-bold uppercase tracking-[.18em] text-muted-foreground">Workspace</div>
      <nav className="mt-3 grid gap-1">{navItems.map(({ href, label, icon: Icon }) => <Link key={href} href={href} onClick={() => setOpen(false)} data-testid={`link-nav-${label.toLowerCase().replaceAll(' ', '-')}`} className={cx('group flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition', location === href ? 'bg-primary text-primary-foreground shadow-sm' : 'text-muted-foreground hover:bg-secondary hover:text-foreground')}><Icon size={17} /><span>{label}</span>{label === 'Expiry watch' && <span className={cx('ml-auto h-2 w-2 rounded-full', location === href ? 'bg-accent' : 'bg-accent')} />}</Link>)}</nav>
      <div className="mt-8 px-2 text-[10px] font-bold uppercase tracking-[.18em] text-muted-foreground">Account</div>
      <nav className="mt-3 grid gap-1"><Link href="/settings" onClick={() => setOpen(false)} data-testid="link-nav-settings" className={cx('flex items-center gap-3 rounded-lg px-3 py-2.5 text-sm font-medium transition', location === '/settings' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground hover:bg-secondary hover:text-foreground')}><Settings size={17} />Settings</Link></nav>
      <div className="absolute bottom-5 left-5 right-5 border-t border-border pt-4"><div className="flex items-center gap-3"><div className="grid h-9 w-9 place-items-center rounded-full bg-accent/20 text-sm font-bold text-accent-foreground">{initials}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{me.data.name}</p><p className="truncate text-xs text-muted-foreground">{me.data.email}</p></div><button data-testid="button-logout-sidebar" className="text-muted-foreground hover:text-destructive" onClick={() => logout.mutate(undefined, { onSuccess: () => setLocation('/login') })} aria-label="Log out"><LogOut size={16} /></button></div></div>
    </aside>
    {open && <button className="fixed inset-0 z-20 bg-foreground/20 lg:hidden" onClick={() => setOpen(false)} aria-label="Close navigation" data-testid="button-overlay-menu" />}
    <div className="lg:pl-64"><header className="sticky top-0 z-10 flex h-16 items-center justify-between border-b border-border bg-background/90 px-5 backdrop-blur lg:px-10"><button className="text-foreground lg:hidden" onClick={() => setOpen(true)} aria-label="Open menu" data-testid="button-open-menu"><Menu size={21} /></button><div className="hidden text-sm text-muted-foreground lg:block">Pharmacy operations / <span className="text-foreground">{navItems.find((item) => item.href === location)?.label ?? 'Settings'}</span></div><div className="ml-auto flex items-center gap-4 text-muted-foreground"><span className="hidden items-center gap-2 text-xs sm:flex"><span className="h-2 w-2 rounded-full bg-primary" />Workspace live</span><Link href="/settings" data-testid="link-header-settings"><Settings size={18} /></Link></div></header><main className="mx-auto max-w-[1440px] px-5 py-7 lg:px-10 lg:py-9">{children}</main></div>
  </div>;
}

function PublicNav() {
  return <header className="mx-auto flex max-w-7xl items-center justify-between px-5 py-5 lg:px-8"><Brand /><div className="flex items-center gap-3"><Link href="/login" data-testid="link-login-nav" className="hidden px-3 py-2 text-sm font-semibold text-muted-foreground hover:text-foreground sm:block">Sign in</Link><Link href="/register" data-testid="link-register-nav" className="inline-flex h-10 items-center rounded-lg bg-primary px-4 text-sm font-semibold text-primary-foreground shadow-sm hover:-translate-y-0.5">Open workspace <ArrowRight size={15} className="ml-2" /></Link></div></header>;
}

function Landing() {
  return <div className="grain min-h-[100dvh] overflow-hidden bg-background"><PublicNav /><section className="relative mx-auto max-w-7xl px-5 pb-20 pt-14 lg:px-8 lg:pb-28 lg:pt-24"><div className="absolute -right-40 top-0 h-[520px] w-[520px] rounded-full bg-accent/10 blur-3xl" /><div className="relative grid items-center gap-14 lg:grid-cols-[1.05fr_.95fr]"><div className="animate-rise"><div className="mb-7 inline-flex items-center gap-2 rounded-full border border-primary/15 bg-primary/5 px-3 py-1.5 text-xs font-bold uppercase tracking-[.12em] text-primary"><ShieldCheck size={14} /> Clinical clarity, every shift</div><h1 className="max-w-3xl text-5xl font-semibold leading-[.98] tracking-[-.055em] text-foreground sm:text-7xl">Know what’s safe to <span className="text-primary">dispense.</span></h1><p className="mt-7 max-w-xl text-lg leading-relaxed text-muted-foreground">PharmaFlow keeps medicine stock, batch expiry, and FEFO dispensing in one calm workspace — so your team can move quickly without guessing.</p><div className="mt-9 flex flex-wrap gap-3"><Link href="/register" data-testid="link-hero-register" className="inline-flex h-12 items-center rounded-lg bg-primary px-5 text-sm font-bold text-primary-foreground shadow-md hover:-translate-y-0.5">Start for your pharmacy <ArrowRight size={16} className="ml-2" /></Link><Link href="/login" data-testid="link-hero-login" className="inline-flex h-12 items-center rounded-lg border border-border bg-card px-5 text-sm font-bold hover:border-primary/40">Sign in to workspace</Link></div></div><div className="relative animate-rise delay-2"><div className="relative rounded-2xl border border-border bg-card p-4 shadow-[0_25px_80px_rgba(41,73,73,.13)]"><div className="rounded-xl bg-primary px-5 py-5 text-primary-foreground"><div className="flex items-start justify-between"><div><p className="text-xs font-medium text-primary-foreground/70">Morning inventory brief</p><p className="mt-1 text-2xl font-semibold">All signals clear</p></div><ShieldCheck size={26} /></div><div className="mt-6 h-2 overflow-hidden rounded-full bg-primary-foreground/20"><div className="h-full w-[86%] rounded-full bg-accent" /></div><div className="mt-2 flex justify-between text-xs text-primary-foreground/70"><span>Sellable coverage</span><span>86%</span></div></div><div className="grid grid-cols-2 gap-3 p-2 pt-5"><div className="rounded-xl border border-border bg-background p-4"><p className="text-xs text-muted-foreground">Expiring in 30 days</p><p className="mt-2 text-3xl font-semibold">08</p><p className="mt-1 text-xs text-accent-foreground">Needs review</p></div><div className="rounded-xl border border-border bg-background p-4"><p className="text-xs text-muted-foreground">Today’s dispensing</p><p className="mt-2 text-3xl font-semibold">42</p><p className="mt-1 text-xs text-primary">FEFO allocated</p></div></div></div><div className="absolute -bottom-6 -left-6 rounded-xl border border-border bg-card px-4 py-3 shadow-md"><p className="flex items-center gap-2 text-xs font-semibold"><span className="grid h-5 w-5 place-items-center rounded-full bg-primary text-primary-foreground"><Check size={12} /></span> Expiry risk surfaced early</p></div></div></div></section><section className="border-y border-border bg-card/60"><div className="mx-auto grid max-w-7xl gap-px px-5 py-5 sm:grid-cols-3 lg:px-8"><div className="flex items-center gap-3 py-3 sm:border-r sm:border-border"><Clock3 className="text-primary" size={20} /><div><p className="text-sm font-semibold">FEFO by default</p><p className="text-xs text-muted-foreground">The right batch, every time.</p></div></div><div className="flex items-center gap-3 py-3 sm:justify-center sm:border-r sm:border-border"><Bell className="text-accent" size={20} /><div><p className="text-sm font-semibold">Expiry watch</p><p className="text-xs text-muted-foreground">Risk never hides in a spreadsheet.</p></div></div><div className="flex items-center gap-3 py-3 sm:justify-end"><ClipboardList className="text-primary" size={20} /><div><p className="text-sm font-semibold">Audit-ready history</p><p className="text-xs text-muted-foreground">Every dispense, accounted for.</p></div></div></div></section><section className="mx-auto max-w-7xl px-5 py-20 lg:px-8 lg:py-28"><div className="max-w-xl"><p className="text-xs font-bold uppercase tracking-[.16em] text-accent-foreground">Built for the counter</p><h2 className="mt-4 text-4xl font-semibold tracking-[-.04em] sm:text-5xl">Quiet software for high-stakes work.</h2><p className="mt-5 text-muted-foreground">No noisy dashboards. Just a clear answer to the questions that matter: what do we have, what is at risk, and what is safe to move next?</p></div><div className="mt-12 grid gap-5 md:grid-cols-3"><div className="rounded-2xl border border-border bg-secondary/60 p-6"><div className="mb-12 text-primary"><Package size={24} /></div><h3 className="text-xl font-semibold">See stock health</h3><p className="mt-2 text-sm leading-relaxed text-muted-foreground">A live view of sellable, low, and unavailable medicines across your shelves.</p></div><div className="rounded-2xl border border-border bg-primary p-6 text-primary-foreground md:translate-y-5"><div className="mb-12 text-accent"><Zap size={24} /></div><h3 className="text-xl font-semibold">Dispense with certainty</h3><p className="mt-2 text-sm leading-relaxed text-primary-foreground/70">PharmaFlow allocates earliest-expiry stock first, automatically.</p></div><div className="rounded-2xl border border-border bg-secondary/60 p-6"><div className="mb-12 text-primary"><TrendingDown size={24} /></div><h3 className="text-xl font-semibold">Act before waste</h3><p className="mt-2 text-sm leading-relaxed text-muted-foreground">Expiry alerts arrive with enough context to make the next action obvious.</p></div></div></section><footer className="mx-auto flex max-w-7xl flex-wrap items-center justify-between gap-4 border-t border-border px-5 py-7 text-xs text-muted-foreground lg:px-8"><Brand /><span>Inventory clarity for independent pharmacies.</span></footer></div>;
}

function AuthLayout({ children, title, eyebrow, copy }: { children: ReactNode; title: string; eyebrow: string; copy: string }) {
  return <div className="grain grid min-h-[100dvh] bg-background lg:grid-cols-[.85fr_1.15fr]"><div className="hidden bg-primary p-10 text-primary-foreground lg:flex lg:flex-col lg:justify-between"><Brand /><div><p className="text-xs font-bold uppercase tracking-[.18em] text-accent">Pharmacy operations, clarified</p><h2 className="mt-5 max-w-md text-5xl font-semibold leading-[1.02] tracking-[-.05em]">A clear next step for every batch.</h2><p className="mt-6 max-w-sm leading-relaxed text-primary-foreground/70">Designed around the pace and responsibility of the dispensary.</p></div><p className="text-xs text-primary-foreground/50">PHARMAFLOW / 01</p></div><div className="flex items-center justify-center p-5 py-10 sm:p-10"><div className="w-full max-w-md"><div className="mb-10 lg:hidden"><Brand /></div><p className="text-xs font-bold uppercase tracking-[.16em] text-accent-foreground">{eyebrow}</p><h1 className="mt-3 text-4xl font-semibold tracking-[-.045em]">{title}</h1><p className="mt-3 text-sm leading-relaxed text-muted-foreground">{copy}</p>{children}</div></div></div>;
}

function Login() {
  const [, setLocation] = useLocation(); const login = useLogin(); const [email, setEmail] = useState(''); const [password, setPassword] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); login.mutate({ data: { email, password } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetMeQueryKey() }); setLocation('/dashboard'); } }); };
  return <AuthLayout eyebrow="Welcome back" title="Sign in to your workspace." copy="Your inventory desk is ready when you are."><form onSubmit={submit} className="mt-8 grid gap-5"><Field label="Email address" type="email" value={email} onChange={setEmail} required placeholder="you@pharmacy.co.uk" autoComplete="email" /><Field label="Password" type="password" value={password} onChange={setPassword} required placeholder="••••••••" autoComplete="current-password" />{login.isError && <div className="rounded-lg bg-red-50 p-3 text-sm text-red-800" data-testid="error-login">The email or password was not recognised. Please try again.</div>}<Button type="submit" disabled={login.isPending} className="mt-2 w-full">{login.isPending ? 'Signing in…' : 'Sign in'} {!login.isPending && <ArrowRight size={16} />}</Button><p className="text-center text-sm text-muted-foreground">New to PharmaFlow? <Link href="/register" data-testid="link-register-from-login" className="font-bold text-primary hover:underline">Create a workspace</Link></p></form></AuthLayout>;
}

function Register() {
  const [, setLocation] = useLocation(); const register = useRegister(); const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [pharmacyName, setPharmacyName] = useState('');
  const submit = (e: FormEvent) => { e.preventDefault(); register.mutate({ data: { name, email, password, pharmacyName } }, { onSuccess: () => { queryClient.invalidateQueries({ queryKey: getGetMeQueryKey() }); setLocation('/dashboard'); } }); };
  return <AuthLayout eyebrow="Set up your pharmacy" title="Start with a clear shelf." copy="Create your secure workspace in under a minute. You can refine your pharmacy details any time."><form onSubmit={submit} className="mt-8 grid gap-4"><Field label="Your name" value={name} onChange={setName} required placeholder="Dr. Amina Rahman" /><Field label="Work email" type="email" value={email} onChange={setEmail} required placeholder="amina@pharmacy.co.uk" autoComplete="email" /><Field label="Password" type="password" value={password} onChange={setPassword} required placeholder="At least 8 characters" autoComplete="new-password" /><Field label="Pharmacy name" value={pharmacyName} onChange={setPharmacyName} required placeholder="Northbank Pharmacy" />{register.isError && <div className="rounded-lg bg-red-50 p-3 text-sm text-red-800" data-testid="error-register">We couldn’t create your workspace. Check your details and try again.</div>}<Button type="submit" disabled={register.isPending} className="mt-2 w-full">{register.isPending ? 'Creating workspace…' : 'Create workspace'} {!register.isPending && <ArrowRight size={16} />}</Button><p className="text-center text-sm text-muted-foreground">Already have an account? <Link href="/login" data-testid="link-login-from-register" className="font-bold text-primary hover:underline">Sign in</Link></p></form></AuthLayout>;
}

function PageHeader({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><p className="text-xs font-bold uppercase tracking-[.16em] text-accent-foreground">{eyebrow}</p><h1 className="mt-2 text-3xl font-semibold tracking-[-.045em] sm:text-4xl">{title}</h1><p className="mt-2 max-w-xl text-sm text-muted-foreground">{copy}</p></div>{action}</div>;
}

function Dashboard() {
  const summary = useGetInventorySummary({ query: { queryKey: getGetInventorySummaryQueryKey() } });
  if (summary.isLoading) return <><PageHeader eyebrow="Today" title="Good morning." copy="Loading your inventory brief…" /><Skeleton rows={5} /></>;
  if (summary.isError || !summary.data) return <ErrorState onRetry={() => summary.refetch()} />;
  const s = summary.data;
  return <div className="animate-rise"><PageHeader eyebrow="Today / inventory brief" title="Good morning." copy="Here’s the signal from your pharmacy floor." action={<Link href="/dispense" data-testid="link-quick-dispense" className="inline-flex h-11 items-center rounded-lg bg-primary px-4 text-sm font-bold text-primary-foreground shadow-sm"><Zap size={16} className="mr-2 text-accent" /> Quick dispense</Link>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Medicines tracked" value={s.totalMedicines} note="Across catalog" icon={Package} /><Metric label="Sellable stock" value={s.totalSellableStock} note="Units ready to move" icon={TrendingUp} accent /><Metric label="Low stock" value={s.lowStockMedicines} note={s.lowStockMedicines ? 'Review reorder levels' : 'No action needed'} icon={TrendingDown} warn={s.lowStockMedicines > 0} /><Metric label="Expiry watch" value={s.expiringSoonBatches} note={`${s.expiredBatches} expired batches`} icon={Bell} warn={s.expiringSoonBatches > 0 || s.expiredBatches > 0} /></div><div className="mt-6 grid gap-5 xl:grid-cols-[1.25fr_.75fr]"><section className="rounded-xl border border-border bg-card p-5 shadow-sm"><div className="flex items-center justify-between"><div><h2 className="font-semibold">Recent dispensing</h2><p className="mt-1 text-xs text-muted-foreground">Latest FEFO allocations from your team.</p></div><Link href="/history" data-testid="link-view-history" className="text-xs font-bold text-primary hover:underline">View history <ArrowRight size={13} className="ml-1 inline" /></Link></div>{s.recentDispensing?.length ? <div className="mt-5 divide-y divide-border">{s.recentDispensing.slice(0, 5).map((r) => <DispensingRow key={r.id} record={r} />)}</div> : <div className="mt-5"><EmptyState icon={ClipboardList} title="No dispensing yet" body="Your recent dispensing activity will appear here." action={<Link href="/dispense" data-testid="link-start-dispensing" className="text-sm font-bold text-primary">Make first dispense</Link>} /></div>}</section><section className="rounded-xl border border-border bg-primary p-5 text-primary-foreground shadow-sm"><div className="flex items-start justify-between"><div><p className="text-xs font-bold uppercase tracking-[.14em] text-primary-foreground/60">Safety check</p><h2 className="mt-2 text-2xl font-semibold">Expiry risk is visible.</h2></div><ShieldCheck className="text-accent" size={25} /></div><p className="mt-4 text-sm leading-relaxed text-primary-foreground/70">Open your expiry watch to review batches before they become waste.</p><div className="mt-8 grid grid-cols-2 gap-3"><div className="rounded-lg bg-primary-foreground/10 p-3"><p className="text-2xl font-semibold">{s.expiringSoonBatches}</p><p className="mt-1 text-xs text-primary-foreground/65">Expiring soon</p></div><div className="rounded-lg bg-primary-foreground/10 p-3"><p className="text-2xl font-semibold">{s.expiredBatches}</p><p className="mt-1 text-xs text-primary-foreground/65">Expired</p></div></div><Link href="/alerts" data-testid="link-review-alerts" className="mt-6 inline-flex items-center text-sm font-bold text-accent">Review expiry watch <ArrowRight size={15} className="ml-2" /></Link></section></div></div>;
}

function Metric({ label, value, note, icon: Icon, accent, warn }: { label: string; value: number; note: string; icon: typeof Package; accent?: boolean; warn?: boolean }) {
  return <div className="rounded-xl border border-border bg-card p-5 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md"><div className="flex items-center justify-between"><p className="text-xs font-bold uppercase tracking-[.1em] text-muted-foreground">{label}</p><span className={cx('grid h-8 w-8 place-items-center rounded-lg', warn ? 'bg-orange-100 text-orange-700' : 'bg-secondary text-primary')}><Icon size={16} /></span></div><p className={cx('mt-5 text-3xl font-semibold tracking-[-.04em]', accent && 'text-primary')}>{value.toLocaleString()}</p><p className={cx('mt-1 text-xs', warn ? 'text-orange-700' : 'text-muted-foreground')}>{note}</p></div>;
}

function DispensingRow({ record }: { record: { id: number; medicineName: string; totalQuantity: number; dispensedBy: string; dispensedAt: string; remainingSellableStock: number } }) {
  return <div className="flex items-center gap-3 py-3" data-testid={`row-dispensing-${record.id}`}><div className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-secondary text-primary"><ClipboardList size={16} /></div><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{record.medicineName}</p><p className="text-xs text-muted-foreground">{record.dispensedBy} · {fmtDateTime(record.dispensedAt)}</p></div><div className="text-right"><p className="text-sm font-semibold">−{record.totalQuantity}</p><p className="text-[11px] text-muted-foreground">{record.remainingSellableStock} remaining</p></div></div>;
}

function Medicines() {
  const [page, setPage] = useState(1); const [search, setSearch] = useState(''); const [sortBy, setSortBy] = useState<'name' | 'createdAt' | 'sellableStock'>('name'); const [order, setOrder] = useState<'asc' | 'desc'>('asc'); const [formOpen, setFormOpen] = useState(false); const [editing, setEditing] = useState<any>(null); const list = useListMedicines({ page, limit: 10, search: search || undefined, sortBy, order }, { query: { queryKey: getListMedicinesQueryKey({ page, limit: 10, search: search || undefined, sortBy, order }) } }); const create = useCreateMedicine(); const update = useUpdateMedicine(); const remove = useDeleteMedicine();
  const [form, setForm] = useState({ name: '', genericName: '', category: '', manufacturer: '', unit: 'pack', reorderLevel: '0', description: '' });
  const openForm = (item?: any) => { setEditing(item ?? null); setForm(item ? { name: item.name, genericName: item.genericName, category: item.category, manufacturer: item.manufacturer, unit: item.unit, reorderLevel: String(item.reorderLevel), description: item.description ?? '' } : { name: '', genericName: '', category: '', manufacturer: '', unit: 'pack', reorderLevel: '0', description: '' }); setFormOpen(true); };
  const save = (e: FormEvent) => { e.preventDefault(); const data = { ...form, reorderLevel: Number(form.reorderLevel) }; const done = () => { setFormOpen(false); queryClient.invalidateQueries({ queryKey: getListMedicinesQueryKey() }); }; editing ? update.mutate({ medicineId: editing.id, data }, { onSuccess: done }) : create.mutate({ data }, { onSuccess: done }); };
  const del = (id: number) => { if (window.confirm('Delete this medicine? It must have no stock.')) remove.mutate({ medicineId: id }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getListMedicinesQueryKey() }) }); };
  return <div className="animate-rise"><PageHeader eyebrow="Catalog / medicines" title="Medicine catalog" copy="Keep your product list precise, searchable, and ready for the counter." action={<Button data-testid="button-add-medicine" onClick={() => openForm()}><Plus size={16} /> Add medicine</Button>} /><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search className="absolute left-3 top-3 text-muted-foreground" size={17} /><input data-testid="input-search-medicines" value={search} onChange={(e) => { setSearch(e.target.value); setPage(1); }} placeholder="Search by medicine, generic name, or manufacturer" className="h-11 w-full rounded-lg border border-input bg-card pl-10 pr-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/15" /></div><div className="flex gap-2"><select data-testid="select-sort-medicines" value={sortBy} onChange={(e) => setSortBy(e.target.value as typeof sortBy)} className="h-11 rounded-lg border border-input bg-card px-3 text-sm"><option value="name">Sort: name</option><option value="createdAt">Sort: newest</option><option value="sellableStock">Sort: stock</option></select><Button data-testid="button-toggle-order" variant="outline" className="h-11 min-h-0 w-11 p-0" onClick={() => setOrder(order === 'asc' ? 'desc' : 'asc')}><ArrowDown size={16} className={order === 'asc' ? 'rotate-180' : ''} /></Button></div></div>{list.isLoading ? <Skeleton rows={6} /> : list.isError ? <ErrorState onRetry={() => list.refetch()} /> : !list.data?.items?.length ? <EmptyState icon={Package} title="No medicines found" body={search ? 'Try a different search term.' : 'Add your first medicine to start tracking stock.'} action={<Button onClick={() => openForm()}><Plus size={15} /> Add medicine</Button>} /> : <div className="overflow-hidden rounded-xl border border-border bg-card shadow-sm"><div className="hidden grid-cols-[1.5fr_1fr_.65fr_.7fr_1fr_auto] gap-4 border-b border-border bg-secondary/50 px-5 py-3 text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground md:grid"><span>Medicine</span><span>Category</span><span>Sellable</span><span>Batch health</span><span>Status</span><span /></div>{list.data.items.map((m) => <div key={m.id} data-testid={`row-medicine-${m.id}`} className="grid gap-3 border-b border-border px-5 py-4 transition last:border-0 hover:bg-secondary/30 md:grid-cols-[1.5fr_1fr_.65fr_.7fr_1fr_auto] md:items-center md:gap-4"><div className="flex items-center justify-between md:block"><div><Link href={`/medicines/${m.id}`} data-testid={`link-medicine-${m.id}`} className="font-semibold hover:text-primary hover:underline">{m.name}</Link><p className="mt-0.5 text-xs text-muted-foreground">{m.genericName || 'Generic name not set'} · {m.unit}</p></div><div className="md:hidden"><StatusBadge status={m.status} /></div></div><p className="text-sm text-muted-foreground">{m.category || 'Uncategorised'}</p><p className="font-mono text-sm">{m.sellableStock.toLocaleString()}</p><p className="text-sm text-muted-foreground">{m.activeBatches} active / {m.expiredBatches} expired</p><div className="hidden md:block"><StatusBadge status={m.status} /></div><div className="flex gap-1 md:justify-end"><Button data-testid={`button-edit-medicine-${m.id}`} aria-label={`Edit ${m.name}`} variant="ghost" className="h-8 min-h-0 w-8 p-0" onClick={() => openForm(m)}><Pencil size={15} /></Button><Button data-testid={`button-delete-medicine-${m.id}`} aria-label={`Delete ${m.name}`} variant="ghost" className="h-8 min-h-0 w-8 p-0 text-destructive hover:bg-red-50" onClick={() => del(m.id)}><Trash2 size={15} /></Button></div></div>)}</div>} {list.data?.pagination && <div className="mt-5"><Pagination {...list.data.pagination} onPage={setPage} /></div>}{formOpen && <MedicineDialog form={form} setForm={setForm} editing={editing} pending={create.isPending || update.isPending} onClose={() => setFormOpen(false)} onSave={save} />}</div>;
}

function MedicineDialog({ form, setForm, editing, pending, onClose, onSave }: { form: any; setForm: (form: any) => void; editing: any; pending: boolean; onClose: () => void; onSave: (e: FormEvent) => void }) {
  const set = (key: string) => (value: string) => setForm({ ...form, [key]: value });
  return <Dialog title={editing ? 'Edit medicine' : 'Add medicine'} onClose={onClose}><form onSubmit={onSave} className="grid gap-4 sm:grid-cols-2"><Field label="Name" value={form.name} onChange={set('name')} required placeholder="Amoxicillin 500mg" /><Field label="Generic name" value={form.genericName} onChange={set('genericName')} placeholder="Amoxicillin" /><Field label="Category" value={form.category} onChange={set('category')} placeholder="Antibiotic" /><Field label="Manufacturer" value={form.manufacturer} onChange={set('manufacturer')} placeholder="Northbank Labs" /><Field label="Unit" value={form.unit} onChange={set('unit')} required placeholder="box" /><Field label="Reorder level" type="number" min={0} value={form.reorderLevel} onChange={set('reorderLevel')} /><div className="sm:col-span-2"><TextareaField label="Description" value={form.description} onChange={set('description')} placeholder="Optional dispensing notes" /></div><div className="flex justify-end gap-2 border-t border-border pt-4 sm:col-span-2"><Button type="button" variant="ghost" onClick={onClose}>Cancel</Button><Button type="submit" disabled={pending}>{pending ? 'Saving…' : editing ? 'Save changes' : 'Add medicine'}</Button></div></form></Dialog>;
}

function Dialog({ title, children, onClose }: { title: string; children: ReactNode; onClose: () => void }) {
  return <div className="fixed inset-0 z-50 grid place-items-center bg-foreground/30 p-4 backdrop-blur-sm"><div className="max-h-[90dvh] w-full max-w-xl overflow-y-auto rounded-2xl border border-border bg-card p-5 shadow-[0_20px_70px_rgba(30,58,58,.2)] sm:p-7"><div className="mb-6 flex items-center justify-between"><h2 className="text-xl font-semibold tracking-tight">{title}</h2><button onClick={onClose} aria-label="Close dialog" data-testid="button-close-dialog" className="grid h-8 w-8 place-items-center rounded-full text-muted-foreground hover:bg-secondary"><X size={17} /></button></div>{children}</div></div>;
}

function MedicineDetailPage() {
  const [, params] = useRoute('/medicines/:medicineId'); const id = Number(params?.medicineId); const detail = useGetMedicine(id, { query: { queryKey: getGetMedicineQueryKey(id) } }); const create = useCreateBatch(); const update = useUpdateBatch(); const remove = useDeleteBatch(); const [batchOpen, setBatchOpen] = useState(false); const [editing, setEditing] = useState<any>(null); const [form, setForm] = useState({ batchNumber: '', expiryDate: '', quantity: '0', purchasePrice: '0', sellingPrice: '0' });
  const open = (b?: any) => { setEditing(b ?? null); setForm(b ? { batchNumber: b.batchNumber, expiryDate: b.expiryDate.slice(0, 10), quantity: String(b.quantity), purchasePrice: String(b.purchasePrice), sellingPrice: String(b.sellingPrice) } : { batchNumber: '', expiryDate: '', quantity: '0', purchasePrice: '0', sellingPrice: '0' }); setBatchOpen(true); };
  const save = (e: FormEvent) => { e.preventDefault(); const data = { ...form, quantity: Number(form.quantity), purchasePrice: Number(form.purchasePrice), sellingPrice: Number(form.sellingPrice) }; const done = () => { setBatchOpen(false); queryClient.invalidateQueries({ queryKey: getGetMedicineQueryKey(id) }); queryClient.invalidateQueries({ queryKey: getListBatchesQueryKey() }); }; editing ? update.mutate({ batchId: editing.id, data }, { onSuccess: done }) : create.mutate({ medicineId: id, data }, { onSuccess: done }); };
  if (detail.isLoading) return <Skeleton rows={7} />; if (detail.isError || !detail.data) return <ErrorState onRetry={() => detail.refetch()} />; const m = detail.data;
  const del = (batchId: number) => { if (window.confirm('Delete this empty batch?')) remove.mutate({ batchId }, { onSuccess: () => queryClient.invalidateQueries({ queryKey: getGetMedicineQueryKey(id) }) }); };
  return <div className="animate-rise"><Link href="/medicines" data-testid="link-back-medicines" className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-foreground"><ArrowLeft size={15} /> Medicine catalog</Link><PageHeader eyebrow="Medicine / detail" title={m.name} copy={m.genericName ? `${m.genericName} · ${m.manufacturer || 'Manufacturer not set'}` : 'Medicine detail'} action={<Button onClick={() => open()} data-testid="button-add-batch"><Plus size={16} /> Add batch</Button>} /><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Metric label="Sellable stock" value={m.sellableStock} note={`${m.physicalStock} physical units`} icon={Package} accent /><Metric label="Active batches" value={m.activeBatches} note={`${m.expiredBatches} expired`} icon={ClipboardList} /><Metric label="Reorder level" value={m.reorderLevel} note="Units threshold" icon={SlidersHorizontal} warn={m.sellableStock <= m.reorderLevel} /><div className="rounded-xl border border-border bg-card p-5 shadow-sm"><p className="text-xs font-bold uppercase tracking-[.1em] text-muted-foreground">Earliest expiry</p><p className="mt-5 text-xl font-semibold">{fmtDate(m.earliestExpiry)}</p><div className="mt-2"><StatusBadge status={m.status} /></div></div></div><section className="mt-6 overflow-hidden rounded-xl border border-border bg-card shadow-sm"><div className="border-b border-border px-5 py-4"><h2 className="font-semibold">Batches</h2><p className="mt-1 text-xs text-muted-foreground">Stock is allocated from the earliest expiry date first.</p></div>{m.batches?.length ? <div className="divide-y divide-border">{m.batches.map((b) => <div key={b.id} data-testid={`row-batch-${b.id}`} className="grid gap-3 px-5 py-4 transition hover:bg-secondary/30 sm:grid-cols-[1.3fr_1fr_.7fr_.9fr_auto] sm:items-center"><div><p className="font-mono text-sm font-bold">{b.batchNumber}</p><p className="mt-1 text-xs text-muted-foreground">Added {fmtDate(b.createdAt)}</p></div><div><p className="text-sm">{fmtDate(b.expiryDate)}</p><p className={cx('mt-1 text-xs', b.daysRemaining < 0 ? 'text-destructive' : b.daysRemaining <= 30 ? 'text-orange-700' : 'text-muted-foreground')}>{b.daysRemaining < 0 ? `${Math.abs(b.daysRemaining)} days overdue` : `${b.daysRemaining} days remaining`}</p></div><p className="font-mono text-sm">{b.quantity.toLocaleString()} <span className="font-sans text-xs text-muted-foreground">{m.unit}</span></p><StatusBadge status={b.status} /><div className="flex gap-1 sm:justify-end"><Button variant="ghost" className="h-8 min-h-0 w-8 p-0" aria-label="Edit batch" data-testid={`button-edit-batch-${b.id}`} onClick={() => open(b)}><Pencil size={15} /></Button><Button variant="ghost" className="h-8 min-h-0 w-8 p-0 text-destructive hover:bg-red-50" aria-label="Delete batch" data-testid={`button-delete-batch-${b.id}`} onClick={() => del(b.id)}><Trash2 size={15} /></Button></div></div>)}</div> : <div className="p-5"><EmptyState icon={ClipboardList} title="No batches yet" body="Add the first incoming batch to make this medicine sellable." action={<Button onClick={() => open()}><Plus size={15} /> Add batch</Button>} /></div>}</section>{batchOpen && <Dialog title={editing ? 'Edit batch' : 'Add batch'} onClose={() => setBatchOpen(false)}><form onSubmit={save} className="grid gap-4 sm:grid-cols-2"><Field label="Batch number" value={form.batchNumber} onChange={(v) => setForm({ ...form, batchNumber: v })} required placeholder="NB-2408-A" /><Field label="Expiry date" type="date" value={form.expiryDate} onChange={(v) => setForm({ ...form, expiryDate: v })} required /><Field label="Quantity" type="number" min={0} value={form.quantity} onChange={(v) => setForm({ ...form, quantity: v })} required /><Field label="Purchase price" type="number" step={0.01} min={0} value={form.purchasePrice} onChange={(v) => setForm({ ...form, purchasePrice: v })} required /><Field label="Selling price" type="number" step={0.01} min={0} value={form.sellingPrice} onChange={(v) => setForm({ ...form, sellingPrice: v })} required /><div className="flex justify-end gap-2 border-t border-border pt-4 sm:col-span-2"><Button type="button" variant="ghost" onClick={() => setBatchOpen(false)}>Cancel</Button><Button type="submit" disabled={create.isPending || update.isPending}>{create.isPending || update.isPending ? 'Saving…' : 'Save batch'}</Button></div></form></Dialog>}</div>;
}

function Dispense() {
  const [search, setSearch] = useState(''); const [selected, setSelected] = useState<any>(null); const [quantity, setQuantity] = useState('1'); const [done, setDone] = useState<any>(null); const inventory = useSearchInventory({ search: search || undefined, page: 1, limit: 8 }, { query: { queryKey: getSearchInventoryQueryKey({ search: search || undefined, page: 1, limit: 8 }) } }); const stock = useGetMedicineInventory(selected?.id ?? 0, { query: { enabled: !!selected, queryKey: getGetMedicineInventoryQueryKey(selected?.id ?? 0) } }); const dispense = useDispense();
  const submit = () => { if (!selected) return; dispense.mutate({ data: { medicineId: selected.id, quantity: Number(quantity) } }, { onSuccess: (result) => { setDone(result); queryClient.invalidateQueries({ queryKey: getGetMedicineInventoryQueryKey(selected.id) }); queryClient.invalidateQueries({ queryKey: getGetInventorySummaryQueryKey() }); queryClient.invalidateQueries({ queryKey: getListDispensingQueryKey() }); } }); };
  return <div className="animate-rise"><PageHeader eyebrow="Counter / dispense" title="Dispense with certainty." copy="Select a medicine, confirm sellable stock, and let FEFO choose the batches." /><div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><section className="rounded-xl border border-border bg-card p-5 shadow-sm"><div className="flex items-center justify-between"><h2 className="font-semibold">1. Find a medicine</h2><Search size={18} className="text-muted-foreground" /></div><div className="relative mt-4"><Search className="absolute left-3 top-3 text-muted-foreground" size={17} /><input autoFocus data-testid="input-search-dispense" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Search medicine name" className="h-11 w-full rounded-lg border border-input bg-background pl-10 pr-3 text-sm outline-none focus:border-primary focus:ring-2 focus:ring-primary/15" /></div><div className="mt-4">{inventory.isLoading ? <Skeleton rows={4} /> : inventory.isError ? <ErrorState onRetry={() => inventory.refetch()} /> : inventory.data?.items?.length ? <div className="grid gap-2">{inventory.data.items.map((m) => <button key={m.id} data-testid={`button-select-medicine-${m.id}`} onClick={() => { setSelected(m); setDone(null); }} className={cx('flex items-center justify-between rounded-lg border p-3 text-left transition hover:border-primary/60', selected?.id === m.id ? 'border-primary bg-primary/5 ring-1 ring-primary' : 'border-border')}><div><p className="text-sm font-semibold">{m.name}</p><p className="mt-0.5 text-xs text-muted-foreground">{m.genericName || 'Generic name not set'}</p></div><div className="text-right"><p className="font-mono text-sm">{m.sellableStock}</p><p className="text-[11px] text-muted-foreground">sellable</p></div></button>)}</div> : <EmptyState icon={Search} title="No matches" body="Try a medicine name or generic name." />}</div></section><section className="rounded-xl border border-border bg-card p-5 shadow-sm"><h2 className="font-semibold">2. Confirm allocation</h2>{!selected ? <div className="mt-4"><EmptyState icon={Zap} title="Choose a medicine first" body="FEFO details will appear here once you select a medicine." /></div> : stock.isLoading ? <div className="mt-5"><Skeleton rows={4} /></div> : stock.isError || !stock.data ? <div className="mt-5"><ErrorState onRetry={() => stock.refetch()} /></div> : <div className="mt-5"><div className="rounded-xl bg-primary p-5 text-primary-foreground"><p className="text-xs uppercase tracking-[.12em] text-primary-foreground/65">Selected medicine</p><div className="mt-1 flex items-center justify-between gap-3"><h3 className="text-xl font-semibold">{stock.data.medicine.name}</h3><span className="font-mono text-sm">{stock.data.medicine.sellableStock} sellable</span></div></div><div className="mt-5"><label className="text-sm font-semibold">Quantity to dispense</label><div className="mt-2 flex gap-3"><input data-testid="input-dispense-quantity" type="number" min={1} max={stock.data.medicine.sellableStock} value={quantity} onChange={(e) => setQuantity(e.target.value)} className="h-12 w-28 rounded-lg border border-input bg-background px-3 font-mono text-lg outline-none focus:border-primary focus:ring-2 focus:ring-primary/15" /><Button data-testid="button-dispense" onClick={submit} disabled={dispense.isPending || Number(quantity) < 1 || Number(quantity) > stock.data.medicine.sellableStock}>{dispense.isPending ? 'Allocating…' : 'Confirm dispense'} <ArrowRight size={16} /></Button></div></div><div className="mt-6"><div className="mb-3 flex items-center gap-2 text-xs font-bold uppercase tracking-[.12em] text-muted-foreground"><Clock3 size={14} /> FEFO allocation order</div><div className="grid gap-2">{stock.data.eligibleBatches.map((b, i) => <div key={b.id} className="flex items-center justify-between rounded-lg border border-border px-3 py-3"><div className="flex items-center gap-3"><span className="grid h-6 w-6 place-items-center rounded-full bg-secondary text-xs font-bold text-primary">{i + 1}</span><div><p className="font-mono text-sm font-bold">{b.batchNumber}</p><p className="text-xs text-muted-foreground">Expires {fmtDate(b.expiryDate)}</p></div></div><p className="font-mono text-sm">{b.quantity} units</p></div>)}</div></div>{dispense.isError && <div className="mt-4 rounded-lg bg-red-50 p-3 text-sm text-red-800" data-testid="error-dispense">Dispensing could not be completed. Stock may have changed — refresh and try again.</div>}{done && <div className="mt-4 rounded-lg border border-teal-200 bg-teal-50 p-4 text-sm text-teal-900" data-testid="status-dispense-success"><div className="flex items-center gap-2 font-bold"><Check size={16} /> Dispense recorded</div><p className="mt-1">Allocated {done.totalQuantity} units. {done.remainingSellableStock} sellable units remain.</p><Link href="/history" className="mt-2 inline-flex items-center text-xs font-bold underline" data-testid="link-dispense-history">View dispensing history</Link></div>}</div>}</section></div></div>;
}

function Alerts() {
  const [tab, setTab] = useState<'expiring' | 'expired'>('expiring'); const [page, setPage] = useState(1); const [days, setDays] = useState(30); const expiring = useListExpiringAlerts({ days, page, limit: 10 }, { query: { queryKey: getListExpiringAlertsQueryKey({ days, page, limit: 10 }), enabled: tab === 'expiring' } }); const expired = useListExpiredAlerts({ page, limit: 10 }, { query: { queryKey: getListExpiredAlertsQueryKey({ page, limit: 10 }), enabled: tab === 'expired' } }); const data = tab === 'expiring' ? expiring.data : expired.data; const loading = tab === 'expiring' ? expiring.isLoading : expired.isLoading; const error = tab === 'expiring' ? expiring.isError : expired.isError; const retry = tab === 'expiring' ? expiring.refetch : expired.refetch;
  return <div className="animate-rise"><PageHeader eyebrow="Safety / expiry watch" title="Nothing slips past." copy="Review batches approaching expiry or already out of date before they reach the counter." /><div className="mb-5 flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div className="inline-flex w-fit rounded-lg border border-border bg-card p-1"><button data-testid="button-tab-expiring" onClick={() => { setTab('expiring'); setPage(1); }} className={cx('rounded-md px-4 py-2 text-sm font-semibold', tab === 'expiring' ? 'bg-primary text-primary-foreground' : 'text-muted-foreground')}>Expiring soon</button><button data-testid="button-tab-expired" onClick={() => { setTab('expired'); setPage(1); }} className={cx('rounded-md px-4 py-2 text-sm font-semibold', tab === 'expired' ? 'bg-destructive text-destructive-foreground' : 'text-muted-foreground')}>Expired</button></div>{tab === 'expiring' && <label className="flex items-center gap-2 text-sm text-muted-foreground">Window <select data-testid="select-alert-days" value={days} onChange={(e) => { setDays(Number(e.target.value)); setPage(1); }} className="h-10 rounded-lg border border-input bg-card px-3 font-semibold text-foreground"><option value={14}>14 days</option><option value={30}>30 days</option><option value={60}>60 days</option><option value={90}>90 days</option></select></label>}</div>{loading ? <Skeleton rows={6} /> : error ? <ErrorState onRetry={() => retry()} /> : !data?.items?.length ? <EmptyState icon={ShieldCheck} title={tab === 'expiring' ? 'No upcoming expiry alerts' : 'No expired stock'} body={tab === 'expiring' ? `No batches expire within ${days} days.` : 'Your expired stock queue is clear.'} /> : <div className="overflow-hidden rounded-xl border border-border bg-card shadow-sm"><div className="hidden grid-cols-[1.5fr_1fr_.75fr_1fr_auto] gap-4 border-b border-border bg-secondary/50 px-5 py-3 text-[10px] font-bold uppercase tracking-[.12em] text-muted-foreground md:grid"><span>Medicine</span><span>Batch</span><span>Quantity</span><span>Expiry</span><span>Status</span></div>{data.items.map((a) => <div key={a.id} data-testid={`row-alert-${a.id}`} className="grid gap-3 border-b border-border px-5 py-4 last:border-0 md:grid-cols-[1.5fr_1fr_.75fr_1fr_auto] md:items-center md:gap-4"><div><Link href={`/medicines/${a.medicineId}`} data-testid={`link-alert-medicine-${a.id}`} className="font-semibold hover:text-primary hover:underline">{a.medicineName}</Link><p className="mt-1 text-xs text-muted-foreground md:hidden">Batch {a.batchNumber} · {a.quantity} units</p></div><p className="font-mono text-sm">{a.batchNumber}</p><p className="font-mono text-sm">{a.quantity}</p><div><p className="text-sm">{fmtDate(a.expiryDate)}</p><p className={cx('mt-1 text-xs', a.daysRemaining < 0 ? 'text-destructive' : 'text-orange-700')}>{a.daysRemaining < 0 ? `${Math.abs(a.daysRemaining)} days overdue` : `${a.daysRemaining} days remaining`}</p></div><StatusBadge status={a.status} /></div>)}</div>}{data?.pagination && <div className="mt-5"><Pagination {...data.pagination} onPage={setPage} /></div>}</div>;
}

function HistoryPage() {
  const [page, setPage] = useState(1); const [order, setOrder] = useState<'asc' | 'desc'>('desc'); const history = useListDispensing({ page, limit: 10, order }, { query: { queryKey: getListDispensingQueryKey({ page, limit: 10, order }) } });
  return <div className="animate-rise"><PageHeader eyebrow="Audit / dispensing" title="Dispensing history" copy="A complete record of what left the pharmacy, when, and from which FEFO allocation." action={<Button variant="outline" data-testid="button-toggle-history-order" onClick={() => setOrder(order === 'desc' ? 'asc' : 'desc')}><CalendarDays size={16} /> {order === 'desc' ? 'Newest first' : 'Oldest first'} <ChevronDown size={14} /></Button>} />{history.isLoading ? <Skeleton rows={6} /> : history.isError ? <ErrorState onRetry={() => history.refetch()} /> : !history.data?.items?.length ? <EmptyState icon={History} title="No dispensing recorded" body="Completed dispensing transactions will appear here." action={<Link href="/dispense" className="font-bold text-primary" data-testid="link-history-dispense">Go to dispense</Link>} /> : <div className="space-y-3">{history.data.items.map((r) => <div key={r.id} data-testid={`card-history-${r.id}`} className="rounded-xl border border-border bg-card p-5 shadow-sm transition hover:shadow-md"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div className="flex gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-lg bg-secondary text-primary"><ClipboardList size={18} /></div><div><h2 className="font-semibold">{r.medicineName}</h2><p className="mt-1 text-xs text-muted-foreground">{fmtDateTime(r.dispensedAt)} · by {r.dispensedBy}</p></div></div><div className="text-left sm:text-right"><p className="font-mono text-lg font-bold">−{r.totalQuantity} units</p><p className="text-xs text-muted-foreground">{r.remainingSellableStock} sellable remaining</p></div></div><div className="mt-4 flex flex-wrap gap-2">{r.items.map((item) => <span key={item.batchId} className="rounded-md bg-secondary px-2.5 py-1.5 font-mono text-xs text-secondary-foreground">{item.batchNumber} × {item.quantity}</span>)}</div></div>)}</div>}{history.data?.pagination && <div className="mt-5"><Pagination {...history.data.pagination} onPage={setPage} /></div>}</div>;
}

function SettingsPage() {
  const pharmacy = useGetPharmacy({ query: { queryKey: getGetPharmacyQueryKey() } }); const update = useUpdatePharmacy(); const logout = useLogout(); const [, setLocation] = useLocation(); const [form, setForm] = useState<any>(null); const [saved, setSaved] = useState(false);
  useEffect(() => { if (pharmacy.data && !form) setForm({ name: pharmacy.data.name, address: pharmacy.data.address, phone: pharmacy.data.phone, alertThresholdDays: String(pharmacy.data.alertThresholdDays) }); }, [pharmacy.data, form]);
  if (pharmacy.isLoading || !form) return <Skeleton rows={5} />; if (pharmacy.isError) return <ErrorState onRetry={() => pharmacy.refetch()} />;
  const save = (e: FormEvent) => { e.preventDefault(); update.mutate({ data: { ...form, alertThresholdDays: Number(form.alertThresholdDays) } }, { onSuccess: (next) => { setForm({ name: next.name, address: next.address, phone: next.phone, alertThresholdDays: String(next.alertThresholdDays) }); setSaved(true); queryClient.invalidateQueries({ queryKey: getGetPharmacyQueryKey() }); setTimeout(() => setSaved(false), 3000); } }); };
  return <div className="animate-rise max-w-3xl"><PageHeader eyebrow="Account / settings" title="Pharmacy settings" copy="Keep your pharmacy identity and expiry policy up to date." /><form onSubmit={save} className="rounded-xl border border-border bg-card p-5 shadow-sm sm:p-7"><div className="grid gap-5 sm:grid-cols-2"><Field label="Pharmacy name" value={form.name} onChange={(v) => setForm({ ...form, name: v })} required /><Field label="Phone" value={form.phone} onChange={(v) => setForm({ ...form, phone: v })} placeholder="+44 20 0000 0000" /><div className="sm:col-span-2"><Field label="Address" value={form.address} onChange={(v) => setForm({ ...form, address: v })} placeholder="Street, city, postcode" /></div><Field label="Alert threshold (days)" type="number" min={1} value={form.alertThresholdDays} onChange={(v) => setForm({ ...form, alertThresholdDays: v })} /></div><div className="mt-7 flex flex-wrap items-center justify-between gap-3 border-t border-border pt-5"><div>{saved && <p className="flex items-center gap-2 text-sm font-semibold text-primary" data-testid="status-settings-saved"><Check size={16} /> Changes saved</p>}</div><Button type="submit" disabled={update.isPending} data-testid="button-save-settings">{update.isPending ? 'Saving…' : 'Save changes'}</Button></div></form><section className="mt-6 rounded-xl border border-red-200 bg-red-50/70 p-5"><h2 className="font-semibold text-red-900">Session</h2><p className="mt-1 text-sm text-red-900/70">Sign out of this pharmacy workspace on this device.</p><Button type="button" variant="outline" className="mt-4 border-red-200 bg-transparent text-red-800 hover:bg-red-100" onClick={() => logout.mutate(undefined, { onSuccess: () => setLocation('/login') })} data-testid="button-logout-settings"><LogOut size={16} /> Log out</Button></section></div>;
}

function ProtectedRouter() {
  return <Shell><Switch><Route path="/dashboard" component={Dashboard} /><Route path="/medicines" component={Medicines} /><Route path="/medicines/:medicineId" component={MedicineDetailPage} /><Route path="/dispense" component={Dispense} /><Route path="/alerts" component={Alerts} /><Route path="/history" component={HistoryPage} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></Shell>;
}

function Router() {
  const [location] = useLocation();
  const isPublic = ['/', '/login', '/register'].includes(location);
  return <ErrorBoundary resetKey={location}>{isPublic ? <Switch><Route path="/" component={Landing} /><Route path="/login" component={Login} /><Route path="/register" component={Register} /><Route component={NotFound} /></Switch> : <ProtectedRouter />}</ErrorBoundary>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><Router /><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;